{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-kWGyOI/src/diff.js","content":"/**
 * Longest common subsequence over whole lines, and the changes derived from
 * it: a maximal stretch of one document not covered by the subsequence,
 * paired with the stretch of the other document it replaces.
 */

/**
 * Find the matching (side, base) line-index pairs of a longest common
 * subsequence between `side` and `base`, breaking length ties by walking
 * both documents from the start and always taking the earliest match: at
 * each mismatch, advance whichever document has the longer common
 * subsequence remaining once it is advanced, preferring to advance `base`
 * when the two are equally long.
 */
export function computeMatches(side, base) {
  const n = side.length
  const m = base.length
  const width = m + 1
  // suffixLcsLength[i * width + j] is the length of the longest common
  // subsequence of side[i:] and base[j:].
  const suffixLcsLength = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    const row = i * width
    const nextRow = (i + 1) * width
    for (let j = m - 1; j >= 0; j--) {
      suffixLcsLength[row + j] =
        side[i] === base[j]
          ? suffixLcsLength[nextRow + j + 1] + 1
          : Math.max(suffixLcsLength[nextRow + j], suffixLcsLength[row + j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
      continue
    }
    const remainingIfSideAdvances = suffixLcsLength[(i + 1) * width + j]
    const remainingIfBaseAdvances = suffixLcsLength[i * width + j + 1]
    if (remainingIfSideAdvances > remainingIfBaseAdvances) i++
    else j++
  }
  return matches
}

/**
 * Turn the matched-line pairs into changes: each stretch of base lines the
 * subsequence skips over, paired with the stretch of side lines it skips
 * over at the same point.
 */
export function buildChanges(side, base, matches) {
  const changes = []
  let prevSide = -1
  let prevBase = -1
  const boundaries = matches.concat([[side.length, base.length]])
  for (const [si, bj] of boundaries) {
    const baseStart = prevBase + 1
    const baseEnd = bj
    const sideStart = prevSide + 1
    const sideEnd = si
    if (baseEnd > baseStart || sideEnd > sideStart) {
      changes.push({ baseStart, baseEnd, lines: side.slice(sideStart, sideEnd) })
    }
    prevBase = bj
    prevSide = si
  }
  return changes
}

/** The changes a side made relative to the base, tagged with that side's name. */
export function sideChanges(name, side, base) {
  const matches = computeMatches(side, base)
  return buildChanges(side, base, matches).map(change => ({ ...change, side: name }))
}
"}

