function groupIntoRegions(combined) {
  const regions = []
  let i = 0
  while (i < combined.length) {
    const changes = [combined[i]]
    let start = combined[i].baseStart
    let end = combined[i].baseEnd
    i++
    while (i < combined.length && combined[i].baseStart <= end) {
      changes.push(combined[i])
      end = Math.max(end, combined[i].baseEnd)
      i++
    }
    regions.push({ start, end, changes })
  }
  return regions
}

/**
 * A side's version of a whole region: the side's own changes in place, and
 * the base's lines everywhere else in the region.
 */
function sideRepresentation(base, start, end, changes) {
  const lines = []
  let pos = start
  for (const change of changes) {
    if (change.baseStart > pos) lines.push(...base.slice(pos, change.baseStart))
    lines.push(...change.lines)
    pos = change.baseEnd
  }
  if (pos < end) lines.push(...base.slice(pos, end))
  return lines
}

/**
 * Split the base document into the ordered sequence of stable spans and
 * resolved regions that make up the merge, given the changes from each
 * side. A stable span is `{ kind: 'stable', lines }`. A region is
 * `{ kind: 'mine' | 'theirs' | 'both', lines }` when it resolves cleanly, or
 * `{ kind: 'conflict', mine, base, theirs }` when it does not.
 */
export function buildSegments(base, mineChanges, theirsChanges) {
  const combined = mineChanges.concat(theirsChanges).sort((a, b) => a.baseStart - b.baseStart)
  const regions = groupIntoRegions(combined)

  const segments = []
  let cursor = 0
  for (const region of regions) {
    if (region.start > cursor) segments.push({ kind: 'stable', lines: base.slice(cursor, region.start) })

    const mine = region.changes.filter(change => change.side === 'mine')
    const theirs = region.changes.filter(change => change.side === 'theirs')
    const mineLines = sideRepresentation(base, region.start, region.end, mine)
    const theirsLines = sideRepresentation(base, region.start, region.end, theirs)
    const baseLines = base.slice(region.start, region.end)

    if (arraysEqual(mineLines, theirsLines)) segments.push({ kind: 'both', lines: mineLines })
    else if (arraysEqual(mineLines, baseLines)) segments.push({ kind: 'theirs', lines: theirsLines })
    else if (arraysEqual(theirsLines, baseLines)) segments.push({ kind: 'mine', lines: mineLines })
    else segments.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })

    cursor = region.end
  }
  if (cursor < base.length) segments.push({ kind: 'stable', lines: base.slice(cursor, base.length) })

  return segments
}
