 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { sideChanges } from './diff.js'
import { buildSegments } from './regions.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitDocuments(lines) {
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  return docs
}

function renderMerge(segments, withBase) {
  const out = []
  let conflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine', ...segment.mine)
      if (withBase) out.push('||||||| base', ...segment.base)
      out.push('=======', ...segment.theirs, '>>>>>>> theirs')
    } else {
      out.push(...segment.lines)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}

function renderRegions(segments) {
  const out = []
  let conflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`)
    } else {
      out.push(`${segment.kind} ${segment.lines.length}`)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}

function main() {
  const mode = process.argv[2]
  if (!MODES.includes(mode)) fail('usage: cli.js merge|merge2|regions')

  const input = readFileSync(0, 'utf8')
  const lines = splitLines(input)
  const docs = splitDocuments(lines)
  if (docs.length !== 3) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = docs
  const segments = buildSegments(base, sideChanges('mine', mine, base), sideChanges('theirs', theirs, base))

  const { text, conflict } =
    mode === 'regions' ? renderRegions(segments) : renderMerge(segments, mode === 'merge')

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()

